"""
Solution for: count-connected-components-in-lcm-graph
Problem ID: lcb_3680
"""

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Nodes with value > threshold are isolated
        isolated = sum(1 for v in nums if v > threshold)

        # Filter numbers <= threshold
        small = [v for v in nums if v <= threshold]
        if not small:
            return isolated

        # Map value to index
        val_to_idx = {v: i for i, v in enumerate(small)}
        parent = list(range(len(small)))
        rank = [0] * len(small)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # For each d <= threshold, iterate multiples and connect
        first = [-1] * (threshold + 1)
        for d in small:
            idx = val_to_idx[d]
            for m in range(d, threshold + 1, d):
                if first[m] == -1:
                    first[m] = idx
                else:
                    union(idx, first[m])

        roots = set(find(i) for i in range(len(small)))
        return isolated + len(roots)

if __name__ == "__main__":
    # Example test
    sol = Solution()
    print(sol.countComponents([2,4,8,3,9], 5))  # Should output 4
    print(sol.countComponents([2,4,8,3,9,12], 10))  # Should output 2

