import bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # split pattern into three parts
        first = p.find('*')
        second = p.rfind('*')
        a = p[:first]
        b = p[first+1:second]
        c = p[second+1:]

        # helper to find all occurrences using KMP
        def positions(sub):
            if not sub:
                return list(range(len(s)+1))
            n, m = len(s), len(sub)
            # build prefix
            pi = [0]*m
            for i in range(1, m):
                j = pi[i-1]
                while j>0 and sub[i] != sub[j]:
                    j = pi[j-1]
                if sub[i] == sub[j]:
                    j += 1
                pi[i] = j
            pos = []
            j = 0
            for i, ch in enumerate(s):
                while j>0 and ch != sub[j]:
                    j = pi[j-1]
                if ch == sub[j]:
                    j += 1
                if j == m:
                    pos.append(i-m+1)
                    j = pi[j-1]
            return pos

        starts_a = positions(a)
        starts_b = positions(b)
        starts_c = positions(c)

        if a == '' and b == '' and c == '':
            return 0

        best = None
        if b == '':
            for a_start in starts_a:
                a_end = a_start + len(a)
                idx = bisect.bisect_left(starts_c, a_end)
                if idx == len(starts_c):
                    continue
                c_start = starts_c[idx]
                length = c_start + len(c) - a_start
                if best is None or length < best:
                    best = length
        else:
            for b_start in starts_b:
                Q = b_start + len(b) - 1
                bound_a = b_start - len(a)
                if bound_a < 0:
                    continue
                idx_a = bisect.bisect_right(starts_a, bound_a) - 1
                if idx_a < 0:
                    continue
                a_start = starts_a[idx_a]
                idx_c = bisect.bisect_left(starts_c, Q + 1)
                if idx_c == len(starts_c):
                    continue
                c_start = starts_c[idx_c]
                length = c_start + len(c) - a_start
                if best is None or length < best:
                    best = length
        return -1 if best is None else best

if __name__ == "__main__":
    # test example
    s = "abaacbaecebce"
    p = "ba*c*ce"
    print(Solution().shortestMatchingSubstring(s, p))

