#!/usr/bin/env python3
import sys

class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i: int, delta: int) -> None:
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def sum(self, i: int) -> int:
        res = 0
        while i > 0:
            res += self.bit[i]
            i -= i & -i
        return res

    def total(self) -> int:
        return self.sum(self.n)


def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    Q = int(next(it))
    H = [0] + [int(next(it)) for _ in range(N)]

    # nearest taller to the left for each i
    left = [0] * (N + 1)
    stack = []
    for i in range(1, N + 1):
        while stack and H[stack[-1]] < H[i]:
            stack.pop()
        left[i] = stack[-1] if stack else 0
        stack.append(i)

    # bucket positions by their left value
    buckets = [[] for _ in range(N + 1)]  # left value 0..N-1
    for i in range(1, N + 1):
        buckets[left[i]].append(i)

    queries = []  # (l, r, idx)
    for idx in range(Q):
        l = int(next(it))
        r = int(next(it))
        queries.append((l, r, idx))

    queries.sort(key=lambda x: x[0])

    fenwick = Fenwick(N)
    ans = [0] * Q
    qptr = 0
    # process l from 0..N
    for l_val in range(N + 1):
        # add positions with left == l_val
        for pos in buckets[l_val]:
            fenwick.add(pos, 1)
        # answer queries with this l
        while qptr < Q and queries[qptr][0] == l_val:
            _, r_val, qidx = queries[qptr]
            ans[qidx] = fenwick.total() - fenwick.sum(r_val)
            qptr += 1

    sys.stdout.write("\n".join(map(str, ans)))

if __name__ == "__main__":
    solve()

