def compute(N, X, A, B, P, Q):
    # 1-indexed arrays
    X -= 1
    needed = [False]*N
    for arr, perm in [(A, P), (B, Q)]:
        # find cycle containing X: elements reachable by following perm
        visited = [False]*N
        # since perm is permutation, cycle containing X
        cyc = []
        cur = X
        while not visited[cur]:
            visited[cur] = True
            cyc.append(cur)
            cur = perm[cur]-1
        L = len(cyc)
        pos = {node:i for i,node in enumerate(cyc)}
        min_pos = None
        for i in range(N):
            if arr[i]==1:
                if i not in pos:
                    return -1
                if i==X:
                    continue
                ppos=pos[i]
                if min_pos is None or ppos<min_pos:
                    min_pos=ppos
        if min_pos is not None:
            for idx in range(min_pos, L):
                node=cyc[idx]
                needed[node]=True
    return sum(needed)

