def can_reach(N, M, A, B, bad_intervals):
    bad_intervals.sort()
    def good_intervals_in_range(x, y):
        if x > y:
            return []
        res = []
        prev_end = 0
        for L,R in bad_intervals:
            if L > y:
                break
            if R < x:
                continue
            gap_start = max(x, prev_end+1)
            gap_end = min(L-1, y)
            if gap_start <= gap_end:
                res.append([gap_start, gap_end])
            prev_end = max(prev_end, R)
        gap_start = max(x, prev_end+1)
        if gap_start <= y:
            res.append([gap_start, y])
        return res
    from collections import deque
    from bisect import bisect_left
    visited = []
    queue = deque()
    visited.append([1,1])
    queue.append([1,1])
    while queue:
        l,r = queue.popleft()
        expand_start = l + A
        expand_end = r + B
        if expand_start > N:
            continue
        if expand_end > N:
            expand_end = N
        cand_intervals = good_intervals_in_range(expand_start, expand_end)
        for gl,gr in cand_intervals:
            sub_intervals = []
            curr_start = gl
            idx = bisect_left([v[0] for v in visited], curr_start)
            if idx>0 and visited[idx-1][1] >= curr_start:
                idx -= 1
            i = idx
            while i < len(visited) and visited[i][0] <= gr:
                v = visited[i]
                if v[0] > curr_start:
                    sub_intervals.append([curr_start, v[0]-1])
                curr_start = max(curr_start, v[1]+1)
                i += 1
            if curr_start <= gr:
                sub_intervals.append([curr_start, gr])
            for sl,sr in sub_intervals:
                if sl <= sr:
                    if N >= sl and N <= sr:
                        return True
                    iv = bisect_left([v[0] for v in visited], sl)
                    visited.insert(iv, [sl, sr])
                    queue.append([sl, sr])
    return False

