class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        """Return maximum possible minimum Manhattan distance among k selected boundary points."""
        n = len(points)
        p = []
        for x, y in points:
            if y == 0:
                d = x
            elif x == side:
                d = side + y
            elif y == side:
                d = 3 * side - x
            else: # left edge
                d = 4 * side - y
            p.append(d)
        p.sort()
        perim = 4 * side
        q = p + [d + perim for d in p]
        N = n
        def feasible(D: int) -> bool:
            size = 2 * N
            nxt = [size] * size
            j = 0
            for i in range(size):
                if j < i + 1:
                    j = i + 1
                while j < size and q[j] - q[i] < D:
                    j += 1
                nxt[i] = j
            for start in range(N):
                idx = start
                ok = True
                for _ in range(k - 1):
                    idx = nxt[idx]
                    if idx >= start + N:
                        ok = False
                        break
                if ok:
                    return True
            return False
        low, high = 0, perim
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1
        return low

