import sys

def mat_mul(A, B, mod):
    n = len(A)
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        for k in range(n):
            aik = Ai[k]
            if aik == 0:
                continue
            Bk = B[k]
            for j in range(n):
                res[i][j] = (res[i][j] + aik * Bk[j]) % mod
    return res

def mat_pow(mat, exp, mod):
    n = len(mat)
    # identity matrix
    res = [[1 if i==j else 0 for j in range(n)] for i in range(n)]
    base = mat
    while exp:
        if exp & 1:
            res = mat_mul(res, base, mod)
        base = mat_mul(base, base, mod)
        exp >>= 1
    return res

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    p = int(next(it))
    A = [[int(next(it)) for _ in range(N)] for _ in range(N)]
    if p == 2:
        # only one assignment: zero becomes 1
        B = [[1 if A[i][j]==0 else A[i][j] for j in range(N)] for i in range(N)]
        C = mat_pow(B, p, p)
    else:
        K = 0
        A0 = [[0]*N for _ in range(N)]
        for i in range(N):
            row = A[i]
            for j in range(N):
                val = row[j]
                if val == 0:
