import sys, collections

def solve():
    data=sys.stdin.read().splitlines()
    if not data: return
    N=int(data[0].strip())
    lines=data[1:1+N]
    # 0-index
    out=[ [ [] for _ in range(26)] for _ in range(N)]
    inn=[ [ [] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        row=lines[i].strip()
        for j,ch in enumerate(row):
            if ch=='-':
                continue
            c=ord(ch)-97
            out[i][c].append(j)
            inn[j][c].append(i)

    from collections import deque
    def reverse_bfs(targets):
        dist=[[-1]*N for _ in range(N)]
        q=deque()
        for u,v in targets:
            dist[u][v]=0
            q.append((u,v))
        while q:
            u,v=q.popleft()
            d=dist[u][v]
            for c in range(26):
                pu_list=inn[u][c]
                pv_list=inn[v][c]
                if not pu_list or not pv_list:
                    continue
                for pu in pu_list:
                    for pv in pv_list:
                        if dist[pu][pv]==-1:
                            dist[pu][pv]=d+1
                            q.append((pu,pv))
        return dist
    # targets for even: (x,x)
    targets_even=[(i,i) for i in range(N)]
    dist_even=reverse_bfs(targets_even)
    # targets for odd: all (u,v) where edge u->v exists
    targets_odd=[]
    for u in range(N):
        for c in range(26):
            for v in out[u][c]:
                targets_odd.append((u,v))
    dist_odd=reverse_bfs(targets_odd)
    # Build answer
    out_lines=[]
    for i in range(N):
        row=[]
        for j in range(N):
            if i==j:
                row.append('0')
                continue
            best=None
            de=dist_even[i][j]
            if de!=-1:
                best=2*de
            do=dist_odd[i][j]
            if do!=-1:
                val=2*do+1
                if best is None or val<best:
                    best=val
            row.append(str(best if best is not None else -1))
        out_lines.append(' '.join(row))
    sys.stdout.write('\n'.join(out_lines))

if __name__=='__main__':
    solve()

