#!/usr/bin/env python3
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    adj = [[] for _ in range(N+1)]
    deg = [0]*(N+1)
    for _ in range(N-1):
        u = int(next(it)); v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)
        deg[u] += 1
        deg[v] += 1
    deg3_nodes = [i for i in range(1, N+1) if deg[i] == 3]
    # adjacency only between degree-3 nodes
    deg3_adj = [[] for _ in range(N+1)]
    for u in deg3_nodes:
        for v in adj[u]:
            if deg[v] == 3:
                deg3_adj[u].append(v)
    visited = [False]*(N+1)
    ans = 0
    for start in deg3_nodes:
        if not visited[start]:
            stack = [start]
            visited[start] = True
            deg2_set = set()
            while stack:
                u = stack.pop()
                # collect deg-2 neighbors
                for v in adj[u]:
                    if deg[v] == 2:
                        deg2_set.add(v)
                # traverse to other deg3 neighbors
                for v in deg3_adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            k = len(deg2_set)
            ans += k*(k-1)//2
    print(ans)

if __name__ == "__main__":
    solve()

