class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        wlen = n + m - 1
        fixed = [None] * wlen
        class Interval:
            __slots__ = ('start', 'remaining', 'diff')
            def __init__(self, start):
                self.start = start
                self.remaining = m
                self.diff = False
        intervals = []
        pos_to_ints = [[] for _ in range(wlen)]
        # Build intervals for each 'F'
        for i, ch in enumerate(str1):
            if ch == 'F':
                it = Interval(i)
                idx = len(intervals)
                intervals.append(it)
                for p in range(i, i + m):
                    pos_to_ints[p].append(idx)
        # Apply 'T' constraints and update intervals
        for i, ch in enumerate(str1):
            if ch == 'T':
                for k in range(m):
                    pos = i + k
                    c = str2[k]
                    if fixed[pos] is None:
                        fixed[pos] = c
                    elif fixed[pos] != c:
                        return ""
                    for idx in pos_to_ints[pos]:
                        it = intervals[idx]
                        it.remaining -= 1
                        if not it.diff and c != str2[pos - it.start]:
                            it.diff = True
        for it in intervals:
            if it.remaining == 0 and not it.diff:
                return ""
        word = [None] * wlen
        for i, ch in enumerate(fixed):
            if ch is not None:
                word[i] = ch
        letters = 'abcdefghijklmnopqrstuvwxyz'
        for pos in range(wlen):
            if word[pos] is not None:
                continue
            forbid = set()
            for idx in pos_to_ints[pos]:
                it = intervals[idx]
                if not it.diff and it.remaining == 1:
                    forbid_letter = str2[pos - it.start]
                    forbid.add(forbid_letter)
            chosen = None
            for ch in letters:
                if ch not in forbid:
                    chosen = ch
                    break
            if chosen is None:
                return ""
            word[pos] = chosen
            for idx in pos_to_ints[pos]:
                it = intervals[idx]
                if not it.diff and chosen != str2[pos - it.start]:
                    it.diff = True
                it.remaining -= 1
        for it in intervals:
            if not it.diff:
                return ""
        return ''.join(word)

