from typing import List

class Solution:
    def minDifference(self, nums: List[int]) -> int:
        max_adj_diff = 0
        neighbours = []
        for i in range(len(nums) - 1):
            a, b = nums[i], nums[i + 1]
            if a != -1 and b != -1:
                max_adj_diff = max(max_adj_diff, abs(a - b))
            elif a == -1 and b != -1:
                neighbours.append(b)
            elif a != -1 and b == -1:
                neighbours.append(a)
        if not neighbours:
            return 0
        lo, hi = min(neighbours), max(neighbours)
        x_y_diff = (hi - lo + 1) // 2
        return max(max_adj_diff, x_y_diff)

