#!/usr/bin/env python3
import sys
sys.setrecursionlimit(1_000_000)
NEG = -10**18

def get_top_k_sum(vals, k):
    if k == 0:
        return 0
    if len(vals) < k:
        return NEG
    if vals[k-1] == NEG:
        return NEG
    return sum(vals[:k])


def solve():
    import sys
    it = iter(sys.stdin.read().split())
    n = int(next(it))
    g=[[] for _ in range(n)]
    for _ in range(n-1):
        a=int(next(it))-1; b=int(next(it))-1
        g[a].append(b); g[b].append(a)
    parent=[-1]*n
    order=[0]
    for v in order:
        for to in g[v]:
            if to==parent[v]:
                continue
            parent[to]=v
            order.append(to)
    dp_true=[NEG]*n
    dp_false=[NEG]*n
    # process in reverse order
    for v in reversed(order):
        child_vals=[]
        for to in g[v]:
            if to==parent[v]:
                continue
            child_vals.append((dp_true[to], dp_false[to]))
        nf_vals=[cf for _,cf in child_vals]
        f_vals=[ct for ct,_ in child_vals]
        best_vals=[f if f>nf else nf for f,nf in zip(f_vals,nf_vals)]
        # sorted lists for candidate calculations
        nf_sorted=sorted([v for v in nf_vals if v!=NEG], reverse=True)
        best_sorted=sorted([(v, idx) for idx,v in enumerate(best_vals) if v!=NEG], key=lambda x: x[0], reverse=True)
        best_only_vals=[v for v,_ in best_sorted]
        pref=[0]
        for v in best_only_vals:
            pref.append(pref[-1]+v)
        best_rank=[-1]*len(child_vals)
        for pos,(val,idx) in enumerate(best_sorted):
            best_rank[idx]=pos
        # allowed t when parentIncluded
        t_allowed=[0,3]
        bestTrue=NEG
        bestFalse=NEG
        num_child=len(child_vals)
        for t in t_allowed:
            if t>num_child:
                continue
            # candidate for node not flagged
            if (t+1)!=4:
                nf_sum=get_top_k_sum(nf_sorted,t)
                if nf_sum!=NEG:
                    size=1+nf_sum
                    if size>bestFalse:
                        bestFalse=size
            # candidate for node flagged by itself
            if (t+1)==4:
                # node flagged
                best_sum=get_top_k_sum(best_only_vals,t)
                if best_sum!=NEG:
                    size=1+best_sum
                    if size>bestTrue:
                        bestTrue=size
            # candidate for flag via child
            if (t+1)!=4:
                for idx,(ct,cf) in enumerate(child_vals):
                    if ct==NEG:
                        continue
                    # choose child idx as flagged via ct
                    if t-1==0:
                        excl_sum=0
                    else:
                        # compute sum of top t-1 best excluding idx
                        rank=best_rank[idx]
                        if rank>=t-1:
                            excl_sum=pref[t-1]
                        else:
                            excl_sum=pref[t]-best_only_vals[rank]
                    if excl_sum==NEG:
                        continue
                    total=1+ct+excl_sum
                    if total>bestTrue:
                        bestTrue=total
        dp_true[v]=bestTrue
        dp_false[v]=bestFalse
    # root is 0
    res=dp_true[0]
    if res<=0:
        print(-1)
    else:
        print(res)
if __name__=='__main__':
    solve()

