import itertools, collections, math

def counts(N, M):
    pts=[]
    for bits in range(1<< (N*(N-1)//2)):
        ed=[]
        idx=0
        for i in range(N):
            for j in range(i+1,N):
                if bits>>idx &1:
                    ed.append((i,j))
                idx+=1
        if len(ed)!=M:
            continue
        # BFS
        g=[set() for _ in range(N)]
        for a,b in ed:
            g[a].add(b); g[b].add(a)
        # connectivity
        seen=set([0])
        q=[0]
        while q:
            u=q.pop()
            for v in g[u]:
                if v not in seen:
                    seen.add(v); q.append(v)
        if len(seen)!=N:
            continue
        d=[None]*N
        d[0]=0
        q=[0]
        while q:
            u=q.pop()
            for v in g[u]:
                if d[v] is None:
                    d[v]=d[u]+1
                    q.append(v)
        ev=sum(1 for x in d if x%2==0)
        od=sum(1 for x in d if x%2==1)
        if ev==od:
            pts.append(ed)
    return len(pts)

